ApprovalCenter.apiDocs:
# ApprovalCenter API

## ApprovalCenterProps

```typescript
type ApprovalCenterProps = {
  /**
   * Дополнительный класс для корневого элемента
   */
  className?: string;
  /**
   * Кастомные CSS-стили для контейнера
   */
  $css?: string | CSSObject | FlattenSimpleInterpolation;
  /**
   * Параметры превью
   */
  preview?: ApprovalCenterPreview;
  /**
   * Параметры вкладок
   */
  tabs: ApprovalCenterTabs;
  /**
   * Параметры вкладки жизненного цикла
   */
  lifeCycle?: LifeCycleItem[];
  /**
   * Параметры вкладки истории
   */
  history?: HistoryItem[];
};
```

## ApprovalCenterPreview

```typescript
type ApprovalCenterPreview = {
  /**
   * Параметры кнопки превью
   */
  button?: PreviewButton;
  /**
   * Переключить превью в режим загрузки
   */
  loading?: boolean;
};
```

## PreviewButton

```typescript
type PreviewButton = {
  /**
   * Колбэк, вызываемый по клику
   */
  onClick: () => void;
  /**
   * Текстовая надпись
   */
  text: string;
};
```

## ApprovalCenterTabs

```typescript
type ApprovalCenterTabs = {
  /**
   * Текущая открытая вкладка
   */
  active: 'LIFE_CYCLE';
  /**
   * Список доступных вкладок
   */
  available:
    | ['LIFE_CYCLE', 'HISTORY']
    | ['HISTORY', 'LIFE_CYCLE']
    | ['HISTORY']
    | ['LIFE_CYCLE'];
};
```

## LifeCycleItem

```typescript
type LifeCycleItem = {
  /**
   * Статус
   */
  status: LifeCycleStatus;
  /**
   * Заголовок
   */
  title: string;
  /**
   * Заголовок выполненного действия
   */
  actionTitle?: string;
  /**
   * Дата выполненного действия
   */
  actionDate?: string;
  /**
   * Этапы (аккордеон)
   */
  stages?: StageItem[];
  /**
   * Вспомогательные кнопки
   */
  buttons?: LifeCycleButton[];
};
```

## LifeCycleStatus

```typescript
type LifeCycleStatus = 'DEFAULT' | 'WAIT' | 'SUCCESSFUL' | 'FAILURE';
```

## StageItem

```typescript
type StageItem = {
  /**
   * Статус
   */
  status: StageStatus;
  /**
   * Заголовок
   */
  title: string;
  /**
   * Открыт ли элемент аккордеона
   */
  open?: boolean;
  /**
   * Комментарий
   */
  comment?: string;
  /**
   * Тултип на иконке статуса
   */
  tooltip?: { text: string };
  /**
   * Пометка (обычно звёздочка)
   */
  mark?: { tooltip: { text: string }; icon: ReactNode };
  /**
   * Заголовок действия
   */
  actionTitle?: string;
  /**
   * Заголовок даты
   */
  actionDate?: string;
  /**
   * ФИО людей, отвечающих за согласование
   */
  assignee?: [string, ...string[]];
  /**
   * Вспомогательные кнопки
   */
  buttons?: LifeCycleButton[];
};
```

## StageStatus

