  /**
   * Слот для контента слева
   */
  contentLeft: ReactNode;
  /**
   * Колбэк, вызываемый по клику
   */
  onClick: () => void;
  /**
   * Текстовая надпись
   */
  text: string;
};
```

## HistoryItem

```typescript
type HistoryItem = {
  /**
   * Статус
   */
  status: HistoryItemStatus;
  /**
   * Заголовок действия
   */
  actionTitle: string;
  /**
   * Дата действия
   */
  actionDate: string;
