function DynamicContentRender() {
    const [items, setItems] = useState([1, 2, 3]);

    const addItem = () => {
      setItems((prev) => [...prev, Math.max(...prev, 0) + 1]);
    };

    const removeItem = () => {
      setItems((prev) => (prev.length > 0 ? prev.slice(0, -1) : prev));
    };

    const reset = () => {
      setItems([1, 2, 3]);
    };

    return (
      <DemoContainer>
        <div style={{ marginBottom: 16, display: 'flex', gap: 8 }}>
          <Button
            onClick={addItem}
            style={{
              background: textPositive,
              color: textPrimary,
              border: 'none',
              borderRadius: 4,
              cursor: 'pointer',
            }}
          >
            + Добавить
          </Button>
          <Button
            onClick={removeItem}
            style={{
              background: textNegative,
              color: textPrimary,
              border: 'none',
              borderRadius: 4,
              cursor: 'pointer',
            }}
          >
            − Удалить
          </Button>
          <Button
            onClick={reset}
            style={{
              background: textInfo,
              color: textPrimary,
              border: 'none',
              borderRadius: 4,
              cursor: 'pointer',
            }}
          >
            Сбросить
          </Button>
          <span
            style={{
              alignSelf: 'center',
              marginLeft: 8,
              color: textWarningMinor,
            }}
          >
            Элементов: {items.length}
          </span>
        </div>

        <BlockGradientScroll
          variant="white"
          style={{
            maxHeight: 300,
            overflowY: 'auto',
            padding: 24,
            borderRadius: 8,
            border: `1px solid ${outlineAccent}`,
          }}
        >
          {items.map((id) => (
            <DemoItem key={id}>
              <h3>Элемент {id}</h3>
            </DemoItem>
          ))}
          {items.length === 0 && (
            <div
              style={{
                color: textWarningMinor,
                textAlign: 'center',
                padding: 40,
              }}
            >
              Пусто. Добавь элементы.
            </div>
          )}
        </BlockGradientScroll>
      </DemoContainer>
    );
  }

