          // Максимальная ширина
          maxWidth={360}
          // State для управления ширины
          widthState={[width, setWidth]}
          // Коллбэк, вызывается при смене состояния
          onResize={handleResize}
          // Коллбэк, вызывается при смене состояния
          onToggleCollapse={handleToggle}
          // Управление состоянием панели
