# PageTitle API

## PageTitleProps

```typescript
type PageTitleProps = {
  /**
   * Заголовок страницы (текст)
   */
  title?: string;
  /**
   * Пропсы для TypographyWithAutoTooltip в который обернут title
   */
  titleTypographyProps?: Omit<
    TypographyWithAutoTooltipProps<'H2'>,
    'children' | 'variant'
  >;
