# TextArea API

Обёртка над `TextArea` из `@salutejs/sdds-finai`. Добавляет `onClear`.

## Кастомные пропсы (добавлены в обёртке)

```typescript
type TextAreaProps = TextAreaBaseProps & {
  /**
   * Callback при нажатии на кнопку очистки поля ввода.
   */
  onClear?: () => void;
};
```

## Пропсы из @salutejs/sdds-finai

Компонент принимает все пропсы атомарного `TextArea` из `@salutejs/sdds-finai`.

Полное описание — в документации: [TextArea](https://plasma.sberdevices.ru/sdds-finai/components/textarea/)

curatedStories.code:
import { TextArea } from '@daisforge/ui';

(args: TextAreaProps) => {
    const [value, setValue] = useState('Значение поля');

    return (
      <div style={{ width: '400px' }}>
        <TextArea
          {...args}
          value={value}
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            setValue(e.target.value)
          }
        />
      </div>
    );
  }

import { TextArea } from '@daisforge/ui';

(args: TextAreaProps) => {
    const sizes = ['s'] as const;
    const [values, setValues] = useState<Record<string, string>>({
      l: '',
      m: '',
      s: '',
      xs: '',
    });

    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '1rem',
          width: '400px',
        }}
      >
        {sizes.map((size) => (
          <TextArea
            {...args}
            key={size}
            size={size}
            label={`Size: ${size}`}
            placeholder="Заполните поле"
            value={values[size]}
            onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
              setValues((prev) => ({ ...prev, [size]: e.target.value }))
            }
          />
        ))}
      </div>
    );
  }

import { TextArea } from '@daisforge/ui';

(args: TextAreaProps) => {
    const [value1, setValue1] = useState('Текст для очистки');
    const [value2, setValue2] = useState('Текст с иконкой');
    const [value3, setValue3] = useState('');
    const [value4, setValue4] = useState('Текст');

    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '1rem',
          width: '400px',
        }}
      >
        <TextArea
          {...args}
          label="onClear + value → крестик"
          value={value1}
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            setValue1(e.target.value)
          }
          onClear={() => setValue1('')}
        />

        <TextArea
          {...args}
          label="onClear + value + contentRight → рядом"
          value={value2}
          contentRight={<IconSb size="s" />}
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            setValue2(e.target.value)
          }
          onClear={() => setValue2('')}
        />

        <TextArea
          {...args}
          label="Пустое значение — крестик скрыт"
          value={value3}
          contentRight={<IconSb size="s" />}
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            setValue3(e.target.value)
          }
          onClear={() => setValue3('')}
        />

        <TextArea
          {...args}
          label="ReadOnly — замок вместо крестика и contentRight"
          value="Только для чтения"
          readOnly
          contentRight={<IconSb size="s" />}
          onClear={() => {}}
        />

        <TextArea
          {...args}
          label="Disabled — замок вместо крестика и contentRight"
          value="Заблокировано"
          disabled
          contentRight={<IconSb size="s" />}
          onClear={() => {}}
        />

        <TextArea
          {...args}
          label="Только contentRight, без onClear"
          value={value4}
          contentRight={<IconSb size="s" />}
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            setValue4(e.target.value)
          }
        />
      </div>
    );
  }

