                content={
                  <>
                    {filteredOverlayItems.map((item) => (
                      <div key={item.id} style={{ width: '100%' }}>
                        {item?.metadata?.labelInPopoverFilter && (
                          <BodyS style={{ marginBottom: '8px' }}>
