  ellipsis?: string;
  maxLines?: number;
  autoTooltip?: CanvasTextAutoTooltip;
}
```

## CanvasTextAutoTooltip

Конфиг авто-тултипа при обрезке текста (проп `autoTooltip`). `boolean` — включить/выключить с дефолтным поведением (полный текст ноды), объект — кастомизация:

```typescript
type CanvasTextAutoTooltip =
  | boolean
  | (CanvasNodeTooltipProps & {
      /** @default true — скрыть можно через false */
      enabled?: boolean;
      /**
       * Переопределение/трансформация текста тултипа. По умолчанию — собственный
       * текст ноды. Вернуть `null` — не показывать.
       */
      text?: string | ((fullText: string) => string | null);
      mouseEnterDelay?: number;
      mouseLeaveDelay?: number;
    });
```

