    );

    return (
      <TableCanvas
        tableConfig={{
          containerStyle: { height: 700 },
          summaryRows: {
            showDefault: true,
            showInControl: false,
          },
        }}
        columnConfig={columnConfig}
        rows={rows}
        bottomSummaryRows={[rows.length]}
      />
    );
