() => {
    const [rows] = useState(createRows);
    const [groupedCols, setGroupedCols] = useState<string[]>([]);
    const [filters, setFilters] = useState({});

    const columnConfig = useMemo<readonly ColumnConfig<Row>[]>(
      () => [
        {
          key: 'id',
          name: 'ID',
          rowsGrouping: { columnGroupLabel: 'ID' },
        },
        {
          key: 'task',
          name: 'Title',
          rowsGrouping: { columnGroupLabel: 'Title' },
        },
        {
          key: 'priority',
          name: 'Priority',
          rowsGrouping: { columnGroupLabel: 'Priority' },
        },
      ],
      [],
    );

    // Общий обработчик для аналитики.
    // e — MouseEvent (undefined для элементов внутри Dropdown).
    // detail — контекст: action, columnKey, size и др.
    // detail.action — одна из констант DOM_METADATA_ACTIONS
    const handleDomMetadataClick = (
      source: string,
      e?: React.MouseEvent<HTMLElement>,
      detail?: Record<string, unknown>,
    ) => {
      // Пример: проверка конкретного действия через константу
      if (detail?.action === DOM_METADATA_ACTIONS.TOGGLE_GROUP) {
        console.debug(
          `[DomMetadata] Группировка по столбцу: ${detail.columnKey}`,
        );
      }
      console.debug(`[DomMetadata] ${source}:`, {
        detail,
        target: e?.currentTarget,
      });
    };

    return (
      <TableCanvas
        tableConfig={{
          containerStyle: { height: '700px' },

          // 1. Группировка строк
          // detail.action: 'toggle-group' | 'reset-groups' | 'custom-item-select'
          // detail.columnKey: ключ столбца (для toggle-group и custom-item-select)
          rowsGrouping: {
            groupByState: [groupedCols, setGroupedCols],
            rowKeyGetter: (row) => row.id.toString(),
            domMetadata: {
              className: 'analytics-grouping',
              dataAttributes: { 'data-feature': 'grouping' },
              onClick: (e, detail) =>
                handleDomMetadataClick('rowsGrouping', e, detail),
            },
          },

          // 2. Кнопка размера строки
          // detail.action: 'change-row-size'
          // detail.size: новый размер ('small' | 'medium' | 'big')
          rowSize: {
            showInControl: true,
            default: 'small',
            available: ['small', 'medium', 'big'],
            domMetadata: {
              className: 'analytics-row-size',
              dataAttributes: { 'data-feature': 'row-size' },
              onClick: (e, detail) =>
                handleDomMetadataClick('rowSize', e, detail),
            },
          },

          // 3. Настройки столбцов: закрепление и видимость
          // pinDomMetadata — detail.action: 'pin-column' | 'unpin-column', detail.columnKey
          // switchDomMetadata — detail.action: 'show-column' | 'hide-column', detail.columnKey
          columnsControl: {
            enable: true,
            pinDomMetadata: {
              className: 'analytics-pin',
              dataAttributes: { 'data-feature': 'pin-column' },
              onClick: (e, detail) =>
                handleDomMetadataClick('pinColumn', e, detail),
            },
            switchDomMetadata: {
              className: 'analytics-switch',
              dataAttributes: { 'data-feature': 'column-visibility' },
              onClick: (e, detail) =>
                handleDomMetadataClick('columnVisibility', e, detail),
            },
          },

          // 4. Таб настроек сайдбара (шестерёнка + крестик закрыть)
          // detail.action: 'toggle-sidebar-tab' (шестерёнка) | 'close-sidebar' (крестик)
          // detail.tabId: id таба (для toggle-sidebar-tab)
          sidebarConfig: {
            defaultTabs: [
              {
                id: 'tableSettings',
                domMetadata: {
                  className: 'analytics-settings',
                  dataAttributes: { 'data-feature': 'settings' },
                  onClick: (e, detail) =>
                    handleDomMetadataClick('settings', e, detail),
                },
              },
            ],
          },

          filtering: {
            state: [filters, setFilters],
          },
        }}
        columnConfig={columnConfig}
        rows={rows}
      />
    );
  }

features.docs:
# Editing (TableCanvas)

**tableConfig.editing + columnConfig.editingCell**

Режим редактирования данных в ячейках таблицы. Условие активации — наличие свойства `editing` в `tableConfig`. Также необходимо сконфигурировать колонки через `editingCell`.

## Ключевые особенности

- Управление режимом редактирования через `enabled` / `defaultEnabled`
- Callback-и при включении, сохранении и отмене (`onEnableEditing`, `onSave`, `onCancel`)
- Контроль редактируемости строк через `rowEditable`
- Поддержка дочерних строк через `subRowsKey`
- Кнопки управления в controlBlock (`showButtons`)
- `editingCell.component` рендерит React-компонент поверх таблицы; `Canvas.*` элементы используйте только в `renderCell`, `renderHeaderCell` и `renderSummaryCell`

## Жизненный цикл

1. Пользователь нажимает кнопку «Редактирование» → вызывается `onEnableEditing`
2. При изменении ячейки → вызывается `onRowsChange` с данными об изменённых строках
3. При нажатии «Сохранить» → вызывается `onSave`
4. При нажатии «Отменить» → вызывается `onCancel`

## Управление состоянием

- **`defaultEnabled`** — начальное состояние (внутренний стейт)
- **`enabled: boolean`** — полностью внешнее управление (без переключения в таблице)
- **`enabled: [boolean, setState]`** — внешний стейт с возможностью переключения в таблице

## Особенности

- `onRowsChange` — обязательный callback, получает обновлённые строки и метаданные (индексы, колонка, before/after)
- `subRowsKey` — обязателен, если дочерние строки хранятся не под ключом `subRows`. Поддерживает вложенность через точку (например, `'data.children'`)
- `showButtons` — по умолчанию `true`, управляет видимостью кнопок в controlBlock

## Управление кнопками (buttons)

Через `editing.buttons` можно передать пропсы кнопкам `save`, `cancel` и `edit`. `onClick` исключён — обработчики задаются через `onSave` / `onCancel` / `onEnableEditing`.

```tsx
editing: {
  buttons: {
    save: { disabled: isSaving, isLoading: isSaving },
    cancel: { disabled: isSaving },
  },
  onSave(disableEditorMode) {
    setIsSaving(true);
    api.save(rows).finally(() => {
      setIsSaving(false);
      disableEditorMode();
    });
  },
}
```

