  onHeaderContextMenuDropdown?: TableGlideInstanceProps<
    RowType,
    SummaryRowType
  >['onHeaderContextMenuDropdown'];
  onCellContextMenuDropdown?: TableGlideInstanceProps<
    RowType,
    SummaryRowType
  >['onCellContextMenuDropdown'];
  onCellContextMenu?: TableGlideInstanceProps<
    RowType,
    SummaryRowType
