import { ColumnConfig, TableCanvas } from '@daisforge/ui';

() => {
    const [isFavorite, setIsFavorite] = useState(true);
    const [rows] = useState(() => {
      const seededRandom = createSeededRandom(42);
      return createRows().map((el) => ({
        ...el,
        id: Math.floor(seededRandom() * 1000),
        date: (() => {
          const date = new Date(
            FIXED_DATE_TIMESTAMP +
              (Math.floor(seededRandom() * 61) - 30) * 86400000,
          );
          return `${String(date.getDate()).padStart(2, '0')}.${String(
            date.getMonth() + 1,
          ).padStart(2, '0')}.${date.getFullYear()}`;
        })(),
      }));
    });

    const filteringStateAndSetter = useState({
      id: '',
      task: '',
      priority: 'All',
      issueType: [],
      complete: '',
      globalFilter: '',
      date: undefined as string | undefined,
    });

    const columnConfig = useMemo<readonly ColumnConfig<Row>[]>(
      () => [
        {
          key: 'id',
          name: 'id',
        },
        {
          key: 'task',
          name: 'Title',
        },
        {
          key: 'date',
          name: 'Date',
          filtering: {
            component: 'custom',
            customRender: (props) => {
              const {
                headerContextState: { filters, setFilters },
              } = props;
              return (
                <Calendar
                  value={filters?.['date']}
                  onChangeValue={(v) => {
                    if (setFilters)
                      setFilters((prev) => ({
                        ...prev,
                        date: v,
                      }));
                  }}
                />
              );
            },
            filter: (filterValue, rowValue) =>
              filterValue ? rowValue === filterValue : true,
            valueInRow: (r) => (r as Row & { date: string })?.date,
            compareWithClearedValue: (clearedValue, currV) =>
              clearedValue === currV,
            keyInFilterState: 'date',
          },
        },

        {
          key: 'priority',
          name: 'Priority',
          filtering: {
            component: 'select',
            selectOptions: {
              type: 'constant',
              options: [
                { value: 'All', text: 'All' },
                { value: 'High', text: 'High' },
                { value: 'Critical', text: 'Critical' },
                { value: 'Medium', text: 'Medium' },
                { value: 'Low', text: 'Low' },
              ],
            },

            keyInFilterState: 'priority',
            valueInRow: (r) => r.priority,
            filter: {
              typeOfValue: 'single',
              filteringType: (fv, rv) => (fv !== 'All' ? rv === fv : true),
            },
          },
        },
        {
          key: 'issueType',
          name: 'Issue Type',
          filtering: {
            beforeList(props) {
              return (
                <TableFilterSelectListItem
                  $size={props.headerContextState.rowSize}
                >
                  custom beforeList
                </TableFilterSelectListItem>
              );
            },
            component: 'select',
            selectOptions: {
              type: 'stateInHeaderContext',
              optionsKeyInHeaderContext: 'issueTypeOptions',
            },
            keyInFilterState: 'issueType',
            valueInRow: (r) => r.issueType,
            filter: {
              typeOfValue: 'multiple',
              filteringType: (fv, rv) =>
                !fv.length || fv.some((fvCurr) => fvCurr === rv),
            },
          },
        },
        {
          key: 'complete',
          name: '% Complete',
        },
      ],
      [],
    );

    const headerContextValue = useMemo(
      () => ({
        issueTypeOptions: [
          { text: 'Bug', value: 'Bug' },
          { text: 'Improvement', value: 'Improvement' },
          { text: 'Epic', value: 'Epic' },
          { text: 'Story', value: 'Story' },
        ],
      }),
      [],
    );

    return (
      <TableCanvas
        tableConfig={{
          containerStyle: { height: '60vh' },
          rowSize: {
            default: 'big',
            showInControl: true,
          },
          fullScreenEnabled: true,
          controlBlock: {
            customFeatures: [
              // Обязательная кастомная фича
              {
                value: 'favorite',
                label: 'Удалить из избранного',
                Icon: IconStar,
                onClick: () => {},
                mandatory: true,
                details: {
                  type: 'switch',
                  label: 'В избранном',
                  checked: isFavorite,
                  onChange: (e) => setIsFavorite(e.target.checked),
                },
              },
            ],
          },
          filtering: {
            state: filteringStateAndSetter,
            filtersInfo: {
              id: {
                label: 'id',
                clearedValue: '',
              },
              task: {
                label: 'task',
                clearedValue: '',
              },
              priority: {
                label: 'Some Label',
                clearedValue: 'All',
              },
              issueType: {
                label: 'issueType',
                clearedValue: [],
              },
              complete: {
                label: 'complete',
                clearedValue: '',
              },
              date: {
                label: 'Дата',
                clearedValue: undefined,
              },
              globalFilter: {
                label: 'Global filter',
                clearedValue: '',
              },
            },
          },
        }}
        columnConfig={columnConfig}
        rows={rows}
        headerContextValue={headerContextValue}
      />
    );
  }

import { ColumnConfig, TableCanvas } from '@daisforge/ui';

() => {
    const columnConfig = useMemo<readonly ColumnConfig<Row>[]>(
      () => [
        {
          key: 'task',
          name: 'Title',
          filtering: {
            component: 'input',
            filter: 'includes',

            valueInRow: (r) => r.task,

            keyInFilterState: 'task',
          },
        },
        {
          key: 'priority',
          name: 'Priority',
          filtering: {
            component: 'select',
            selectOptions: {
              type: 'constant',
              options: [
                { value: 'All', text: 'All' },
                { value: 'High', text: 'High' },
                { value: 'Critical', text: 'Critical' },
                { value: 'Medium', text: 'Medium' },
                { value: 'Low', text: 'Low' },
              ],
            },

            keyInFilterState: 'priority',
            valueInRow: (r) => r.priority,
            filter: {
              typeOfValue: 'single',
              filteringType: (fv, rv) => (fv !== 'All' ? rv === fv : true),
            },
          },
        },
        {
          key: 'issueType',
          name: 'Issue Type',
          filtering: {
            component: 'select',
            selectOptions: {
              type: 'stateInHeaderContext',
              optionsKeyInHeaderContext: 'issueTypeOptions',
            },
            keyInFilterState: 'issueType',
            valueInRow: (r) => r.issueType,
            filter: {
              typeOfValue: 'multiple',
              filteringType: (fv, rv) =>
                !fv.length || fv.some((fvCurr) => fvCurr === rv),
            },
          },
        },
        {
          key: 'complete',
          name: '% Complete',
          filtering: {
            component: 'input',
            keyInFilterState: 'complete',
            valueInRow: (r) => r.complete,
            filter: (fv, rv) => (+rv || 0) >= (+fv || 0),
          },
        },
      ],
      [],
    );

    const rows = useMemo(() => createRows(), []);

    const [filteredRows, setFilteredRows] = useState(rows);

    const filteringStateAndSetter = useState<{
      task: string;
      priority: string;
      issueType: string[];
      complete: string;
    }>({
      task: '',
      priority: 'All',
      issueType: [],
      complete: '',
    });

    const [state] = filteringStateAndSetter;

    useEffect(() => {
      const enabledFilters = Object.entries(state).filter((el) =>
        Array.isArray(el[1]) ? !!el[1].length : !!el[1],
      );
      const filterRows = rows.filter((row) =>
        enabledFilters.every((enabledFilter) => {
          const colValue = row[enabledFilter[0] as keyof typeof row] as string;

          return Array.isArray(enabledFilter[1])
            ? enabledFilter[1].includes(colValue)
            : enabledFilter[1] === colValue.toString() ||
                enabledFilter[1] === 'All';
        }),
      );
      setFilteredRows(filterRows);
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [state]);

    const headerContextValue = useMemo(
      () => ({
        issueTypeOptions: [
          { text: 'Bug', value: 'Bug' },
          { text: 'Improvement', value: 'Improvement' },
          { text: 'Epic', value: 'Epic' },
          { text: 'Story', value: 'Story' },
        ],
      }),
      [],
    );

    return (
      <TableCanvas
        tableConfig={{
          filtering: {
            state: filteringStateAndSetter,
            filtersInfo: {
              task: {
                label: 'task',
                clearedValue: '',
              },
              priority: {
                label: 'Some Label',
                clearedValue: 'All',
              },
              issueType: {
                label: 'issueType',
                clearedValue: [],
              },
              complete: {
                label: 'complete',
                clearedValue: '',
              },
            },
            manualFiltering: true,
          },
        }}
        columnConfig={columnConfig}
        rows={filteredRows}
        headerContextValue={headerContextValue}
      />
    );
  }

import { ColumnConfig, TableCanvas } from '@daisforge/ui/components/TableCanvas';

() => {
