          },
        },

        {
          key: 'q2',
          name: 'Q2',
          contentFormat: {
            type: 'number',
            minimumFractionDigits: 1,
            maximumFractionDigits: 3,
            decimalSeparator: '.',
            thousandSeparator: '_',
            alignContent: 'center',
          },
          subRow: {
            keyOfColumnInSubRow: 'q1',
            contentFormat: {
              type: 'number',
              minimumFractionDigits: 1,
              maximumFractionDigits: 3,
              decimalSeparator: ',',
              thousandSeparator: '.',
              alignContent: 'right',
            },
          },
        },
        {
          key: 'q3',
          name: 'Q3',
          contentFormat: {
            type: 'number',
            minimumFractionDigits: 2,
            locales: ['en-US', 'fr-FR', 'ru-RU'],
          },
          subRow: {
            keyOfColumnInSubRow: 'q1',
          },
        },
        {
          key: 'q4',
          name: 'Q4',
          contentFormat: 'number',
          subRow: {
            keyOfColumnInSubRow: 'q1',
          },
        },
      ],
      [],
    );

    return (
      <TableCanvas
        tableConfig={{
          containerStyle: { height: '700px' },
          subRows: {
            getSubRows: (row) => row?.subRows,
            rowKeyGetter: (row) => row.id,
          },
          resizableColumn: true,
        }}
        columnConfig={columns}
        rows={rows}
      />
    );
  }

