              }}
              columnConfig={columnConfig}
              rows={rows}
            />
          </div>

          <div style={{ width: 340, fontSize: 12 }}>
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                marginBottom: 8,
              }}
            >
              <b>Полученные события ({log.length})</b>
              <button
                type="button"
                onClick={() => setLog([])}
                style={{
                  padding: '4px 10px',
                  borderRadius: 8,
                  border: '1px solid #c7d2e0',
                  background: '#fff',
                  cursor: 'pointer',
                }}
              >
                Очистить
              </button>
            </div>
            {log.length === 0 && (
              <div style={{ color: '#8893a5' }}>Пока пусто</div>
            )}
            {log.map((event, i) => (
              <div
                key={i}
                style={{
                  borderLeft: `3px solid ${LEVEL_COLOR[event.level]}`,
                  padding: '6px 10px',
                  marginBottom: 6,
                  background: '#fafbfc',
                }}
              >
                <div
                  style={{ color: LEVEL_COLOR[event.level], fontWeight: 600 }}
                >
                  {event.type} · {event.code} · {event.level}
                </div>
                <div style={{ color: '#556' }}>{event.message}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

