import { ColumnConfig, TableCanvas } from '@daisforge/ui/components/TableCanvas';

() => {
    const [rows] = useState(createRows);

    const columnConfig = useMemo<readonly ColumnConfig<Row>[]>(
      () => [
        {
          key: 'id',
          name: 'id',
        },
        {
          key: 'task',
          name: 'Title',
        },
        {
          key: 'priority',
          name: 'Priority',
        },
        {
          key: 'loremIpsum',
          name: 'Длинный текст',
          width: 500,
          renderCell: ({ row, theme }) => (
            <Canvas.Container padding={8}>
              <Canvas.Container>
                <Canvas.Text
                  font={theme.baseFontStyle}
                  lineHeight={1.85}
                  wordWrap
                >
                  {row.loremIpsum}
                </Canvas.Text>
              </Canvas.Container>
            </Canvas.Container>
          ),
        },
        {
          key: 'complete',
          name: '% Complete',
        },
      ],
      [],
    );

    const rowHeight: RowHeightFunc<Row> = useCallback((r, currenRowSize) => {
      const symbolWidth = 11.5;

      const paddingInline = 16;
      const widthOfLoremCol = 500 - paddingInline * 2;
      const symbolsInOneLine = Math.round(widthOfLoremCol / symbolWidth);
      const heightOfLineInitial = 22; // в css
      const heightOfLine = heightOfLineInitial - 2; // скорректированный

      const allSymbols = r.loremIpsum.length;

      const countOfLine = Math.ceil(allSymbols / symbolsInOneLine);
      const paddingBlock = Number(
        SIZES[currenRowSize.rowSizeName].cell['padding-block'].slice(0, -2),
      );

      const neededHeight = heightOfLine * countOfLine + paddingBlock * 2;

      return neededHeight > currenRowSize.rowSizeValue
        ? neededHeight
        : currenRowSize.rowSizeValue;
    }, []);

    return (
      <TableCanvas
        tableConfig={{
          containerStyle: { height: 700 },
          rowHeight,
        }}
        columnConfig={columnConfig}
        rows={rows}
      />
    );
  }

features.docs:
# RowMarkers (TableCanvas)

**tableConfig.rowMarkers**

Сервисный столбец с нумерацией строк. Frozen, вставляется первым, исключён из reorder/pin/hide/sort/grouping. Поддерживает плоский и древовидный (`subRows`) режимы любой глубины вложенности.

## Быстрый старт

```tsx
<TableCanvas
  tableConfig={{
    rowMarkers: {
      startIndex: 1,
    },
  }}
  columnConfig={columnConfig}
  rows={rows}
/>
```

## `flatIndex` vs `rowIndex`

Если ветка свернута, но нужно сохранить «сквозные» номера — используйте `flatIndex`.

- полностью раскрыто: `1, 2, 3, 4, 5`
- после сворачивания середины: `1, 2, 5` (а не `1, 2, 3`)

`rowIndex` зависит только от видимых строк — номера будут «прыгать».

## Частичная перерисовка

`getRowMarker` должна быть чистой функцией. Вызывается не только при полной отрисовке таблицы, но и при ховере/скролле — для одной ячейки. Не используйте внешние переменные-счётчики — используйте аргументы (`siblingPath`, `flatIndex`, `siblingIndex`, `parentKey`), они всегда актуальны.

> Подробнее о типах — [RowMarkers API](?path=/docs/локальные-компоненты-tablecanvas-rowmarkers-api--docs)

features.apiDocs:
# RowMarkers API

## RowMarkersTableConfig

```typescript
type RowMarkersTableConfig<
  RowType extends ObjectForExtending = ObjectForExtending,
> = {
  /**
   * Стартовый индекс нумерации (для дефолтной логики без `getRowMarker`).
   * @default 1
   */
  startIndex?: number;

  /**
   * Ширина столбца с нумерацией (в px).
   * Если задан `size` — он приоритетнее.
+  * Если ни `size`, ни `width` не заданы — ширина подстраивается
+  * под глобальный `tableConfig.rowSize` (small=20, medium=32, big=48).
   * @default 32
   */
  width?: number;
  /**
   * Размер столбца. Приоритетнее `width`.
   * - `xs` = 20px
   * - `s` = 32px
   * - `m` = 48px
   */
  size?: 'xs' | 's' | 'm';
  /**
   * Кастомная функция нумерации. Полностью переопределяет дефолтную root-only логику.
   * Вызывается при рендере каждой ячейки столбца нумерации.
   *
   * ⚠️ Вызывается не только при полной отрисовке таблицы, но и при ховере/скролле —
   * для **одной** ячейки. Не используйте внешние переменные-счётчики —
   * используйте аргументы (`siblingPath`, `flatIndex` и др.), они всегда актуальны.
   *
   * @example
   * // Сквозная стабильная нумерация (все строки, номера не прыгают при сворачивании)
   * getRowMarker: ({ flatIndex }) => flatIndex + 1
   *
   * @example
   * // Корневые — номер, дочерние — прочерк
   * getRowMarker: ({ isSubRow, flatIndex }) => isSubRow ? '—' : flatIndex + 1
   *
   * @example
   * // Иерархическая нумерация любой глубины: 1, 1.1, 1.1.1, 1.2, 2
   * getRowMarker: ({ siblingPath }) => siblingPath.map(i => i + 1).join('.')
   */
  getRowMarker?: (args: {
    /** Данные текущей строки. */
    row: RowType;
    /** Уровень строки в дереве: `0` — корневая, `1` — дочерняя, `2` — внучка, и т.д. */
    level: number;
    /** `true`, если строка дочерняя (`level > 0`). */
    isSubRow: boolean;
    /**
     * Индекс строки в **видимых** строках.
     * ⚠️ **Нестабильный** — меняется при сворачивании/разворачивании веток.
     */
    rowIndex: number;
    /**
     * Стабильный 0-based индекс строки в **полном** дереве (включая скрытые/свёрнутые).
     * Не меняется при collapse/expand — подходит для сквозной нумерации.
     */
    flatIndex: number;
    /**
     * Порядковый номер среди siblings одного родителя (0-based).
     * Для корневых строк — порядковый номер среди всех корневых.
     * Для дочерних — порядковый номер среди children одного `parentKey`.
     */
    siblingIndex: number;
    /**
     * Путь siblingIndex-ов от корня до текущей строки (каждый элемент 0-based).
     *
     * Примеры:
     * - корневая строка (2-я): `[1]`
     * - дочерняя (3-й ребёнок 2-го корня): `[1, 2]`
     * - внучка (1-й ребёнок 1-го ребёнка 1-го корня): `[0, 0, 0]`
     *
     * Для иерархической нумерации: `siblingPath.map(i => i + 1).join('.')` → `"1.1.1"`
     *
     * Для плоской таблицы (без subRows): всегда `[siblingIndex]` (один элемент).
     */
    siblingPath: number[];
    /**
     * Ключ родительской строки (`rowKeyGetter(parent)`).
     * `null` для корневых строк. Работает для **любой** глубины вложенности.
     */
    parentKey: string | number | null;
    /** Текущий видимый `flattened` массив строк. */
    rows: readonly RowType[];
  }) => string | number;
};
```

