   * @default 'inside'
   */
  collapseButtonPlacement?: 'inside' | 'above';
  /**
   * Кастомный рендер правого слота кнопки коллапсинга, который используется при collapseButtonPlacement='above'
   */
  collapseButtonAboveRightSlot?: React.ReactNode;
};

