  onItemSelect?: (
    item: ContextMenuDropdownItem,
    context: {
      row: RowType;
      column: CalculatedColumn<RowType, SummaryRowType>;
      selectCell: (enableEditor?: boolean) => void;
    },
    event?: React.SyntheticEvent,
  ) => void;
} & ContextMenuDropDownProps;
```

