export type DefaultOmittedKeys =
  | 'editable'
  | 'sortable'
  | 'sortDescendingFirst'
  | 'renderGroupCell'
  | 'renderEditCell'
  | 'frozen'
  | 'draggable';

export type ColumnDefaultOmitted<
  Row extends ObjectForExtending,
  SummRow = unknown,
> = Omit<ColumnDefault<Row, SummRow>, DefaultOmittedKeys>;

export type { CellClickArgs };
