            contentFormat: {
              customFormat: (val) => `${val}%`,
            },
          },
        },

        {
          key: 'q2',
          name: 'Q2',
          contentFormat: {
            type: 'number',
            minimumFractionDigits: 1,
            maximumFractionDigits: 3,
            decimalSeparator: '.',
            thousandSeparator: '_',
            alignContent: 'center',
          },
          subRow: {
            keyOfColumnInSubRow: 'q1',
            contentFormat: {
              type: 'number',
              minimumFractionDigits: 1,
              maximumFractionDigits: 3,
              decimalSeparator: ',',
              thousandSeparator: '.',
              alignContent: 'right',
            },
          },
        },
        {
          key: 'q3',
          name: 'Q3',
          contentFormat: {
            type: 'number',
            minimumFractionDigits: 2,
