import { ColumnConfig, Table } from '@daisforge/ui';

() => {
    const total = 300;

    const [perPage, setPerPage] = useState(20);
    const [currentPage, setCurrentPage] = useState(1);
    const [rows, setRows] = useState<Row[]>([]);

    const columnConfig = useMemo<readonly ColumnConfig<Row>[]>(
      () => [
        {
          key: 'task',
          name: 'Title',
        },
        {
          key: 'priority',
          name: 'Priority',
        },
        {
          key: 'issueType',
          name: 'Issue Type',
        },
        {
          key: 'complete',
          name: '% Complete',
        },
      ],
      [],
    );

    // Загрузка данных при монтировании и при изменении страницы/perPage
    useEffect(() => {
      const loadData = async () => {
        const data = await getPaginationDataAsync({
          page: currentPage,
          perPage,
          total,
        });
        setRows(data);
      };

      loadData();
    }, [currentPage, perPage]);

    return (
      <Table
        tableConfig={{
          containerStyle: { height: 700 },
          collapsing: {
            enableCollapse: true,
          },
          pagination: {
            count: total,
            perPage,
            value: currentPage, // Важно указать, при активации responsiveSlots
            responsiveSlots: true,
            onChangePageValue(page, scrollToTop) {
              if (typeof page === 'number') {
                setCurrentPage(page);
                scrollToTop();
              }
            },
            async onChange(page, perPage, scrollToTop) {
              if (typeof page === 'number' && typeof perPage === 'number') {
                setCurrentPage(page);
                setPerPage(perPage);
                scrollToTop();
              }
            },
          },
        }}
        columnConfig={columnConfig}
        rows={rows}
      />
    );
  }

