        {
          key: 'id',
          name: (
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
              }}
            >
              id
              <IconSber size="xs" color="inherit" />
            </div>
          ),
        },
        {
          key: 'task',
          name: 'Title',
        },
        {
          key: 'priority',
          name: 'Priority',
        },
        {
          key: 'issueType',
          name: 'Issue Type',
        },
        {
          key: 'complete',
          name: '% Complete',
        },
      ],
      [],
    );

    return (
      <Table
        tableConfig={{
          containerStyle: { height: 700 },
          editing: {
            onRowsChange: setRows,
            rowKeyGetter: (r) => r.id,
          },

          rowDetailPanel: {
            rowKeyGetter: (r) => r.id,
            isRowWithDetail: (r) => r.id === 2 || r.id === 3,
            renderRowDetail: ({ row, onRowChange, tabIndex, rowIdx }) => {
              const tableRef = useRefTableContext();
              const [value, setValue] = useState(row.complete);

              const applyChanging = () => {
                onRowChange({
                  ...row,
                  complete: value,
                });

                if (tableRef) {
                  tableRef.current?.selectCell({
                    idx: 4,
                    rowIdx: rowIdx - 1,
                  });
                }
              };

              return (
                <div>
                  complete {value}
                  <br />
                  <TextField
                    tabIndex={tabIndex}
                    type="number"
                    value={value}
                    onChange={(e) => setValue(+e.target.value)}
                    onKeyDown={inputStopPropagation}
                  />
                  <br />
                  <Button onClick={applyChanging}>применить изменения</Button>
                </div>
              );
            },
            expandButtonColumnKey: 'issueType',
            detailHeight: 300,
            icons: ICONS_PROP,
          },
          enableVirtualization: false,
        }}
        columnConfig={columnConfig}
        rows={rows}
      />
    );
  }

