   */
  summaryChecked?: {
    checked: boolean | SummaryCheckedFunc<RowType, boolean>;
    indeterminate:
      | boolean
      | SummaryCheckedFunc<RowType, boolean, { checkedAll: boolean }>;
    getCountOfChecked: SummaryCheckedFunc<RowType, number>;
    onChange: SummaryCheckedFunc<
      RowType,
      void,
