Table.ColumnConfig.definition:
export type ColumnConfig<
  Row extends ObjectForExtending,
  SummRow = unknown,
> = ColumnDefaultOmitted<Row, SummRow> & {
  /**
   * Если в поле name был передан jsx, то нужно заполнить nameAsString для указания label в разделе Настройки столбцов, либо для отображения label в фильтрах в правом сайдбаре (но приоритет для фильтро будет ниже, чем то, что указали в filtering.sidebarConfig.items, там отдельно можно перезаписать label для фильтров сайдабара)
   */
  nameAsString?: string;
  sortingType?: 'stringSort' | 'numberSort' | Comparator<Row>;
  searching?: {
    valueInRow: (row: Row) => string | number;
  };
  filtering?: {
    keyInFilterState: string;
    /**
     * Обязательно передать в случае НЕ ручной фильтрации. Если на уровне tableConfig.manualFiltering = false или не задан. Иначе фильтрация не отработает.
     */
    valueInRow?: (row: Row) => string | number;
    /**
     * ```FilterCb - (filterValue: string, rowValue: string) => boolean```
     */
  } & (
    | {
        component: 'input';
        filter: 'includes' | 'startWith' | 'equal' | FilterCb<'single'>;
      }
    | {
        component: 'select';
        beforeList?: (
          props: FilterComponentInPopoverProps<
            ObjectForExtending,
            ColumnConfig<Row, SummRow>
          >,
        ) => ReactNode;
        filter:
          | {
              typeOfValue: 'single';
              /**
               * Обязательно передать в случае НЕ ручной фильтрации. Если на уровне tableConfig.manualFiltering = false или не задан. Иначе фильтрация не отработает.
               */
              filteringType?: FilterCb<'single'>;
            }
          | {
              typeOfValue: 'multiple';
              /**
               * Обязательно передать в случае НЕ ручной фильтрации. Если на уровне tableConfig.manualFiltering = false или не задан. Иначе фильтрация не отработает.
               */
              filteringType?: FilterCb<'multiple'>;
            };
        selectOptions:
          | {
              type: 'constant';
              options: SelectOptions[];
            }
          | {
              type: 'stateInHeaderContext';
              /**
               * тип optionsState, который будет в HeaderContext:
               * ```ts
               * {
               * value: string | number;
               * text: string | number;
               * }[];
               * ```
               */
              optionsKeyInHeaderContext: string;
            };
        /**
         * Максимальна высота выпадающего списка в фильтрах колонок / правом сайдбаре.
         * @default "360px"
         */
        listMaxHeight?: string;
      }
    | {
        component: 'custom';
        customRender: (
          props: FilterComponentInPopoverProps<
            ObjectForExtending,
            ColumnConfig<Row, SummRow>
          >,
        ) => ReactNode;
        filter?: (filterValue: unknown, rowValue: unknown) => boolean;
        compareWithClearedValue?: (
          clearedValue: unknown,
          currV: unknown,
        ) => boolean;
      }
  );

  contentFormat?: ContentFormat;

  editingCell?: Editing<Row>;

  subRow?: {
    /**
     * @default false
     */
    isColumnWithArrow?: boolean | ((props: { keyText: KeyText }) => boolean);
    /**
     * @default false
     */
    hideHeaderExpandAllArrow?: boolean;
    /**
     * @default false
     */
    parentKeyAsDefault?: boolean;
    /**
     * @default undefined
     */
    contentFormat?: ContentFormat;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    renderSubRowCell?: RenderSubRowCell<any>;
  } & (
    | {
        keyOfColumnInSubRow:
          | string
          | number
          | ((lvl: number) => string | number);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        editingCell: Editing<any>;
      }
    | {
        editingCell?: undefined;
        keyOfColumnInSubRow?:
          | string
          | number
          | ((lvl: number) => string | number);
      }
  );
  rowsGrouping?: ColumnRowsGrouping<Row, SummRow>;
  keyText?: KeyTextColumnConfig<Row, SummRow>;
};

TableCanvas.ColumnConfig.definition:
export type ColumnConfig<
  Row extends ObjectForExtending,
  SummRow = unknown,
  CustomCtxs extends ObjectForExtending = {},
> = ColumnDefaultOmitted<Row, SummRow, CustomCtxs> & {
  renderCell?: (cellInfo: CellInfo<Row, SummRow, CustomCtxs>) => CellContent;
  renderCellPreview?: RenderCellPreview<Row, SummRow, CustomCtxs>;
  /**
   * Если в поле name был передан jsx, то нужно заполнить nameAsString для указания label в разделе Настройки столбцов, либо для отображения label в фильтрах в правом сайдбаре (но приоритет для фильтро будет ниже, чем то, что указали в filtering.sidebarConfig.items, там отдельно можно перезаписать label для фильтров сайдабара)
   */
  nameAsString?: string;
  /**
   * Текстовое представление ячейки для копирования в clipboard (Ctrl+C).
   * Если не задан, используется `row[column.key]?.toString()`.
   * Для кастомных canvas-ячеек (бейджи, кнопки) рекомендуется указывать явно.
   */
  copyData?: string | ((row: Row) => string);
  sortingType?: 'stringSort' | 'numberSort' | Comparator<Row>;
  searching?: {
    valueInRow: (row: Row) => string | number;
  };
  filtering?: {
    keyInFilterState: string;
    /**
     * Обязательно передать в случае НЕ ручной фильтрации. Если на уровне tableConfig.manualFiltering = false или не задан. Иначе фильтрация не отработает.
     */
    valueInRow?: (row: Row) => string | number;
    /**
     * ```FilterCb - (filterValue: string, rowValue: string) => boolean```
     */
  } & (
    | {
        component: 'input';
        filter: 'includes' | 'startWith' | 'equal' | FilterCb<'single'>;
      }
    | {
        component: 'select';
        beforeList?: (
          props: FilterComponentInPopoverProps<
            ObjectForExtending,
            ColumnConfig<Row, SummRow>
          >,
        ) => ReactNode;
        filter:
          | {
              typeOfValue: 'single';
              /**
               * Обязательно передать в случае НЕ ручной фильтрации. Если на уровне tableConfig.manualFiltering = false или не задан. Иначе фильтрация не отработает.
               */
              filteringType?: FilterCb<'single'>;
            }
          | {
              typeOfValue: 'multiple';
              /**
               * Обязательно передать в случае НЕ ручной фильтрации. Если на уровне tableConfig.manualFiltering = false или не задан. Иначе фильтрация не отработает.
               */
              filteringType?: FilterCb<'multiple'>;
            };
        selectOptions:
          | {
              type: 'constant';
              options: SelectOptions[];
            }
          | {
              type: 'stateInHeaderContext';
              /**
               * тип optionsState, который будет в HeaderContext:
               * ```ts
               * {
               * value: string | number;
               * text: string | number;
               * }[];
               * ```
               */
              optionsKeyInHeaderContext: string;
            };
        /**
         * Максимальна высота выпадающего списка в фильтрах колонок / правом сайдбаре.
         * @default "360px"
         */
        listMaxHeight?: string;
      }
    | {
        component: 'custom';
        customRender: (
          props: FilterComponentInPopoverProps<
            ObjectForExtending,
            ColumnConfig<Row, SummRow>
          >,
        ) => ReactNode;
        filter?: (filterValue: unknown, rowValue: unknown) => boolean;
        compareWithClearedValue?: (
          clearedValue: unknown,
          currV: unknown,
        ) => boolean;
      }
  );

  contentFormat?: ContentFormat;

  editingCell?: Editing<Row, SummRow>;

  subRow?: {
    /**
     * @default false
     */
    isColumnWithArrow?: boolean | ((props: { keyText: KeyText }) => boolean);
    /**
     * @default false
     */
    hideHeaderExpandAllArrow?: boolean;
    /**
     * @default false
     */
    parentKeyAsDefault?: boolean;
    /**
     * @default undefined
     */
    contentFormat?: ContentFormat;

    renderSubRowCell?: RenderSubRowCell<ObjectForExtending>;
  } & (
    | {
        keyOfColumnInSubRow:
          | string
          | number
          | ((lvl: number) => string | number);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        editingCell: Editing<any, any>;
      }
    | {
        editingCell?: undefined;
        keyOfColumnInSubRow?:
          | string
          | number
          | ((lvl: number) => string | number);
      }
  );
  rowsGrouping?: ColumnRowsGrouping<Row, ColumnConfig<Row, SummRow>>;
  keyText?: KeyTextColumnConfig<Row, SummRow>;
  /**
   * Переопределение темы на уровне ячейки. Позволяет менять фон и паддинги для конкретных ячеек.
   * @param cellInfo — информация о ячейке (row, column, ctxs, theme)
   * @param lvl — уровень вложенности (0 для обычных строк, 1+ для subRows)
   * @returns Partial<Theme> — объект переопределений (bgCell, cellHorizontalPadding и др.)
   */
  themeOverride?: (
    cellInfo: CellInfo<Row, SummRow, CustomCtxs>,
    lvl: number,
  ) => CellThemeOverrideResult | undefined;
};

HoverEffectsConfig.definition:
export type HoverEffectsConfig = {
  /**
   * Подсветка строки под курсором.
   * `true` — цвет data-ячеек из темы (`bgRowHovered`); объект — свой цвет.
   * Служебные колонки темнеют `bgServiceRowHovered`, checkbox-строки —
   * `bgSelectedRowHovered` (всегда из темы, `color` их не переопределяет).
   */
  row?: boolean | { color?: string };
};

ColumnGlideInstance.definition:
export type ColumnGlideInstance<
  R extends ObjectForExtending,
  SR,
  CustomCtxs extends ObjectForExtending = {},
> = {
  key: string;
  name: string | CanvasEl;
  nameAsString?: string;
  readonly width?: number;
  isServiceColumn?: boolean;
  isErrorCell?: (row: R) => boolean;
  frozen?: boolean;
  /** Минимальная ширина колонки (px). Ограничивает ресайз и начальную ширину снизу. */
  minWidth?: number;
  /** Максимальная ширина колонки (px). Ограничивает ресайз и начальную ширину сверху. */
  maxWidth?: number;
  /** Максимальная ширина колонки при auto-sizing и grow-распределении (px). Не ограничивает ручной ресайз. */
  maxAutoWidth?: number;
  renderHeaderCell?: (
    cellInfo: HeaderCellInfoGlideInstance<R, SR, CustomCtxs>,
  ) => CanvasContent;
  renderCell?: (
    cellInfo: CellInfoGlideInstance<R, SR, CustomCtxs>,
  ) => CellContent;
  contentAlign?: 'left' | 'right' | 'center';
  copyData?: string | ((row: R) => string);
  editable?: boolean | ((row: R) => boolean);
  renderEditCell?: (
    cellInfo: EditingCellInfoGlideInstance<R, SR, CustomCtxs>,
  ) => ReactNode;
  /**
   * Кастомный рендер preview-ячейки (при двойном клике на readonly-ячейку).
   * 'none' — отключает превью. 'cellEditorAsPreview' — стандартный текстовый превью.
   * Функция — полностью кастомный рендер.
   */
  renderCellPreview?:
    | 'none'
    | 'cellEditorAsPreview'
    | ((
        cellInfo: PreviewCellInfoGlideInstance<R, SR, CustomCtxs>,
      ) => ReactNode);
  renderSummaryCell?: (
    cellInfo: SummaryCellInfoGlideInstance<R, SR, CustomCtxs>,
  ) => CellContent;
  colSpan?:
    | number
    | ((cellInfo: CellInfoGlideInstance<R, SR, CustomCtxs>) => number);
  /** Тултип для ячеек этой колонки. Строка, объект или функция (context) => config | null. */
  cellTooltip?:
    | CanvasNodeTooltipConfig
    | ((context: {
        row: R;
        column: ColumnGlideInstance<R, SR, CustomCtxs>;
        ctxs: CtxsType<CustomCtxs>;
        refTable?: React.Ref<DataEditorRef>;
        colInd?: number;
        rowInd?: number;
        theme?: Theme;
      }) => CanvasNodeTooltipConfig | null);
  /** Тултип для шапки колонки. Строка, объект или функция (context) => config | null. */
  headerCellTooltip?:
    | CanvasNodeTooltipConfig
    | ((context: {
        column: ColumnGlideInstance<R, SR, CustomCtxs>;
        ctxs: CtxsType<CustomCtxs>;
        refTable?: React.Ref<DataEditorRef>;
        colInd?: number;
        theme?: Theme;
      }) => CanvasNodeTooltipConfig | null);
  columnThemeOverride?: (
    cellInfo: CellInfoGlideInstance<R, SR, CustomCtxs>,
  ) => CellThemeOverrideResult | undefined;
};

HeaderContextMenuDropdownProps.definition:
export type HeaderContextMenuDropdownProps<
  RowType extends ObjectForExtending,
  SummaryRowType = unknown,
  CustomCtxs extends ObjectForExtending = ObjectForExtending,
> = ContextMenuDropdownProps & {
  /** Тип конфигурации (всегда 'dropdown') */
  type: 'dropdown';
  /**
   * Функция, возвращающая массив пунктов меню для конкретного заголовка.
   * В асинхронном режиме (задан onOpen) перечитывается реактивно, пока меню
   * открыто: верните скелетон-пункты во время загрузки и реальные — после.
   */
  getDropdownItems: (
    params: TableInfoBase<RowType, SummaryRowType, CustomCtxs>,
  ) => DropdownProps['items'];
  /**
   * Колбэк открытия меню для асинхронной подгрузки. Если getDropdownItems
   * вернул пусто, но onOpen задан — меню всё равно открывается, а потребитель
   * здесь стартует запрос и хранит своё состояние (loading/error/items).
   */
  onOpen?: (params: TableInfoBase<RowType, SummaryRowType, CustomCtxs>) => void;
  /** Обработчик выбора пункта меню */
  onItemSelect?: (
    item: ContextMenuDropdownItem,
    context: TableInfoBase<RowType, SummaryRowType, CustomCtxs>,
    event?: React.SyntheticEvent,
  ) => void;
};

CellContextMenuDropdownProps.definition:
export type CellContextMenuDropdownProps<
  RowType extends ObjectForExtending,
  SummaryRowType,
  CustomCtxs extends ObjectForExtending = ObjectForExtending,
> = ContextMenuDropdownProps & {
  /** Тип конфигурации (всегда 'dropdown') */
  type: 'dropdown';
  /**
   * Функция, возвращающая массив пунктов меню для конкретной ячейки.
   * В асинхронном режиме (задан onOpen) перечитывается реактивно, пока меню
   * открыто: верните скелетон-пункты во время загрузки и реальные — после.
   */
  getDropdownItems: (
    params: TableInfoWithRow<RowType, SummaryRowType, CustomCtxs>,
  ) => DropdownProps['items'];
  /**
   * Колбэк открытия меню для асинхронной подгрузки. Если getDropdownItems
   * вернул пусто, но onOpen задан — меню всё равно открывается, а потребитель
   * здесь стартует запрос и хранит своё состояние (loading/error/items).
   */
  onOpen?: (
    params: TableInfoWithRow<RowType, SummaryRowType, CustomCtxs>,
  ) => void;
  /** Обработчик выбора пункта меню */
  onItemSelect?: (
    item: ContextMenuDropdownItem,
    context: TableInfoWithRow<RowType, SummaryRowType, CustomCtxs>,
    event?: React.SyntheticEvent,
  ) => void;
};

